CREATE TEMPORARY VIEW fx_rate_${grass_region_without_quote} AS
SELECT
    FIRST(exchange_rate) AS exchange_rate
FROM
    mp_order.dim_exchange_rate__reg_s0_live
WHERE
    grass_date = ${local_date}
    AND grass_region = ${grass_region};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_price_${grass_region_without_quote} AS
SELECT
    item_id
    ,coalesce(price_usd, 0) as price_usd
FROM
    mp_item.dim_item__reg_s0_live
WHERE
    tz_type = 'local'
    AND grass_region in (${grass_region})
    AND grass_date = ${local_date};

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_raw_${grass_region_without_quote} AS
SELECT
    exp_group_ids
    ,scenario_tags
    ,array_sort(array_distinct(split(queues, ','))) as queues
    ,item_id
    ,split(queues, ',')[0] AS queue
    ,if(size(split(queues,','))=1,1,0) as is_exclusive
    ,imp_cnt
    ,click_cnt
    ,if(is_back = false, ppv_cnt, 0) as ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,avg_imp_price_local / exchange_rate as avg_imp_price_usd
FROM
    srdi_mart.dwm_sr_data_warehouse_platform_user_item
LEFT JOIN
    fx_rate_${grass_region_without_quote}
WHERE
    grass_region IN (${grass_region})
    AND local_date = ${local_date}
    AND operation IN ('impression', 'click', 'ppv', 'cart', 'order')
    AND queues IS NOT NULL
    AND queues NOT IN ('', ',')
    AND size(exp_group_ids) != 0
    AND array_join(scenario_tags,'|') like '%DA_%'
    ;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_user_exp_base_${grass_region_without_quote} AS
SELECT
    exp_group_ids
    ,scenario_tags
    ,queues
    ,a.item_id
    ,queue
    ,is_exclusive
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,coalesce(avg_imp_price_usd, price_usd) as avg_imp_price_usd
FROM
    dwm_raw_${grass_region_without_quote} as a
LEFT JOIN
    dim_item_price_${grass_region_without_quote} as b
ON
    a.item_id = b.item_id
WHERE
    a.item_id is not null

UNION ALL

SELECT
    exp_group_ids
    ,scenario_tags
    ,queues
    ,item_id
    ,queue
    ,is_exclusive
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,avg_imp_price_usd
FROM
    dwm_raw_${grass_region_without_quote}
WHERE
