    a.item_id = b.item_id
WHERE
    a.item_id is not null

UNION ALL

SELECT
    exp_group_ids
    ,scenario_tags
    ,queues
    ,item_id
    ,queue
    ,is_exclusive
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,avg_imp_price_usd
FROM
    dwm_raw_${grass_region_without_quote}
WHERE
    item_id is null
    -- 0.6% rows have null item_id -> skip join for them
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_user_exp_${grass_region_without_quote} AS
SELECT
    exp_group_ids
    ,scenario_tags
    ,queues
    ,item_id
    ,queue
    ,is_exclusive
    ,sum(imp_cnt) AS imp_cnt
    ,sum(click_cnt) AS click_cnt
    ,sum(ppv_cnt) AS ppv_cnt
    ,sum(cart_cnt) AS cart_cnt
    ,sum(order_cnt) AS order_cnt
    ,sum(gmv) AS gmv
    ,sum(pc2_gmv) AS pc2_gmv
    ,sum(avg_imp_price_usd * imp_cnt) / sum(if(avg_imp_price_usd is null, 0, imp_cnt)) as avg_imp_price_usd
FROM
    dwm_user_exp_base_${grass_region_without_quote}
GROUP BY
    1,2,3,4,5,6;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dwm_explode_data_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,scenario_tags
    ,queues
    ,item_id
    ,queue
    ,is_exclusive
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,avg_imp_price_usd
FROM
    dwm_user_exp_${grass_region_without_quote} dwm_user_exp
    lateral view explode(exp_group_ids) as exp_group_id; 

