CACHE TABLE dwm_filter_tag_${grass_region_without_quote} OPTIONS ('storageLevel' 'DISK_ONLY') AS 
SELECT 
    exp_group_id
    ,scenario_tag
    ,queues
    ,item_id
    ,queue
    ,is_exclusive
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,pc2_gmv
    ,avg_imp_price_usd
FROM
    dwm_explode_data_${grass_region_without_quote} -- reduce exp; originally: dwm_filter_exp_${grass_region_without_quote}
    lateral view explode(scenario_tags) as scenario_tag
WHERE
    scenario_tag IN ('DA_Cart_Unify', 'DA_Buy Again (Me Page)', 
                        'DA_Cart Recommendation', 'DA_mpp_ymal-order_list', 
                        'DA_odp_ymal-order_detail', 'DA_Order Successful Recommendation', 
                        'DA_Daily Discover', 'DA_You May Also Like');

--sql_divide_splitter--

CREATE TEMPORARY VIEW exclusive_data_${grass_region_without_quote} AS
SELECT
    exp_group_id
    ,scenario_tag
    ,queue
    ,COUNT(DISTINCT(IF(is_exclusive = 1, item_id, NULL))) AS queue_exclusive_item_cnt
    ,SUM(if(is_exclusive = 1, imp_cnt, 0)) AS queue_exclusive_imp_cnt
    ,SUM(if(is_exclusive = 1, click_cnt, 0)) AS queue_exclusive_click_cnt
    ,SUM(if(is_exclusive = 1, ppv_cnt, 0)) AS queue_exclusive_ppv_cnt
    ,SUM(if(is_exclusive = 1, cart_cnt, 0)) AS queue_exclusive_cart_cnt
    ,SUM(if(is_exclusive = 1, order_cnt, 0)) AS queue_exclusive_order_cnt
    ,SUM(if(is_exclusive = 1, gmv, 0)) AS queue_exclusive_gmv
FROM
    dwm_filter_tag_${grass_region_without_quote}
GROUP BY
    exp_group_id
    ,scenario_tag
    ,queue;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dws_queue_table_${grass_region_without_quote} AS
SELECT 
    exp_group_id
    ,scenario_tag
    ,recall_queue
    ,COUNT(DISTINCT item_id) AS item_cnt
    ,sum(imp_cnt) AS imp_cnt
    ,sum(click_cnt) AS click_cnt
    ,sum(ppv_cnt) AS ppv_cnt
    ,sum(cart_cnt) AS cart_cnt
    ,sum(order_cnt) AS order_cnt
    ,sum(gmv) AS gmv
    ,sum(pc2_gmv) AS pc2_gmv
    ,sum(avg_imp_price_usd * imp_cnt) / sum(if(avg_imp_price_usd is null, 0, imp_cnt)) as avg_imp_price_usd
FROM
    dwm_filter_tag_${grass_region_without_quote}
    lateral view explode(queues) as recall_queue 
GROUP BY
    exp_group_id
    ,scenario_tag
    ,recall_queue;

--sql_divide_splitter--

INSERT OVERWRITE TABLE ${schema}.dws_sr_data_warehouse_platform_exp_explode_queues_metrics_1d
PARTITION 
(
    grass_region = ${grass_region}, 
    local_date = ${local_date},
    exp_type = 'traffic'
)
SELECT /*+REPARTITION(2)*/
    dws_queue_table.exp_group_id
    ,dws_queue_table.recall_queue as queue
    ,dws_queue_table.scenario_tag
    ,item_cnt
    ,imp_cnt
    ,click_cnt
    ,ppv_cnt
    ,cart_cnt
    ,order_cnt
    ,gmv
    ,queue_exclusive_item_cnt
    ,queue_exclusive_imp_cnt
    ,queue_exclusive_click_cnt
    ,queue_exclusive_cart_cnt
    ,queue_exclusive_ppv_cnt
    ,queue_exclusive_order_cnt
    ,queue_exclusive_gmv
    ,pc2_gmv
    ,avg_imp_price_usd

FROM
    dws_queue_table_${grass_region_without_quote} dws_queue_table
    LEFT JOIN exclusive_data_${grass_region_without_quote} exclusive_data
        ON dws_queue_table.exp_group_id = exclusive_data.exp_group_id
        AND dws_queue_table.recall_queue = exclusive_data.queue
        AND dws_queue_table.scenario_tag = exclusive_data.scenario_tag
